<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_181ad1-e5","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-t-h2 vf-mt-5"} -->
<h2 class="kt-adv-heading7_181ad1-e5 wp-block-kadence-advancedheading vf-t-h2 vf-mt-5" data-kb-block="kb-adv-heading7_181ad1-e5">Good questions.</h2>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_8514f5-65","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-t-lead vf-mt-5"} -->
<p class="kt-adv-heading7_8514f5-65 wp-block-kadence-advancedheading vf-t-lead vf-mt-5" data-kb-block="kb-adv-heading7_8514f5-65">Straight answers, no small print.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"id":2,"borderWidth":["","","",""],"uniqueID":"7_53dc33-7b","kbVersion":2,"className":"vf-accordion"} -->
