<div class="wp-block-kadence-column kadence-column7_41abe7-0b vf-acc-item is-open"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"level":3,"uniqueID":"7_5383a8-d5","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-acc-q"} -->
<h3 class="kt-adv-heading7_5383a8-d5 wp-block-kadence-advancedheading vf-acc-q" data-kb-block="kb-adv-heading7_5383a8-d5">Is there a limit on forms or submissions?</h3>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_9dd962-15","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-acc-a"} -->
<p class="kt-adv-heading7_9dd962-15 wp-block-kadence-advancedheading vf-acc-a" data-kb-block="kb-adv-heading7_9dd962-15">No. Build as many forms as you like and collect as many submissions as you get.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"borderWidth":["","","",""],"uniqueID":"7_4b5b0e-fa","kbVersion":2,"className":"vf-acc-item"} -->
<div class="wp-block-kadence-column kadence-column7_4b5b0e-fa vf-acc-item"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"level":3,"uniqueID":"7_258310-f9","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-acc-q"} -->
<h3 class="kt-adv-heading7_258310-f9 wp-block-kadence-advancedheading vf-acc-q" data-kb-block="kb-adv-heading7_258310-f9">Do I need another plugin?</h3>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_131fbf-12","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-acc-a"} -->
<p class="kt-adv-heading7_131fbf-12 wp-block-kadence-advancedheading vf-acc-a" data-kb-block="kb-adv-heading7_131fbf-12">No. VuloForm works by itself. VuloMail is optional — it makes email delivery more reliable and is required for SMS notifications.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"borderWidth":["","","",""],"uniqueID":"7_5e1890-99","kbVersion":2,"className":"vf-acc-item"} -->
<div class="wp-block-kadence-column kadence-column7_5e1890-99 vf-acc-item"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"level":3,"uniqueID":"7_ce0eb6-4e","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-acc-q"} -->
<h3 class="kt-adv-heading7_ce0eb6-4e wp-block-kadence-advancedheading vf-acc-q" data-kb-block="kb-adv-heading7_ce0eb6-4e">Can I put a form on a site that isn't WordPress?</h3>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_ab1783-4f","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-acc-a"} -->
<p class="kt-adv-heading7_ab1783-4f wp-block-kadence-advancedheading vf-acc-a" data-kb-block="kb-adv-heading7_ab1783-4f">Yes. Copy the snippet under “On another website” on the form's Share tab and paste it into that page's HTML. Your WordPress site must stay online, and the form needs JavaScript on the other site.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"borderWidth":["","","",""],"uniqueID":"7_b12750-00","kbVersion":2,"className":"vf-acc-item"} -->
<div class="wp-block-kadence-column kadence-column7_b12750-00 vf-acc-item"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"level":3,"uniqueID":"7_c328d8-ce","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-acc-q"} -->
<h3 class="kt-adv-heading7_c328d8-ce wp-block-kadence-advancedheading vf-acc-q" data-kb-block="kb-adv-heading7_c328d8-ce">Is there a CAPTCHA?</h3>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_d21ff1-75","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-acc-a"} -->
<p class="kt-adv-heading7_d21ff1-75 wp-block-kadence-advancedheading vf-acc-a" data-kb-block="kb-adv-heading7_d21ff1-75">No. Forms are protected by a hidden trap field, a minimum fill time and a rate limit. Developers can connect another anti-spam service with the vuloform_spam_check filter.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"borderWidth":["","","",""],"uniqueID":"7_d93605-b0","kbVersion":2,"className":"vf-acc-item"} -->
<div class="wp-block-kadence-column kadence-column7_d93605-b0 vf-acc-item"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"level":3,"uniqueID":"7_8922ee-a6","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-acc-q"} -->
<h3 class="kt-adv-heading7_8922ee-a6 wp-block-kadence-advancedheading vf-acc-q" data-kb-block="kb-adv-heading7_8922ee-a6">Can conditional logic be bypassed?</h3>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_844fce-fa","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-acc-a"} -->
<p class="kt-adv-heading7_844fce-fa wp-block-kadence-advancedheading vf-acc-a" data-kb-block="kb-adv-heading7_844fce-fa">No. The rules are checked again on your server. A field hidden by its rules is never stored, and a required field can't be skipped by turning off JavaScript.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"borderWidth":["","","",""],"uniqueID":"7_987a1b-e7","kbVersion":2,"className":"vf-acc-item"} -->
<div class="wp-block-kadence-column kadence-column7_987a1b-e7 vf-acc-item"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"level":3,"uniqueID":"7_c8d068-b0","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-acc-q"} -->
<h3 class="kt-adv-heading7_c8d068-b0 wp-block-kadence-advancedheading vf-acc-q" data-kb-block="kb-adv-heading7_c8d068-b0">Are uploaded files public?</h3>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_91dbce-e8","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-acc-a"} -->
<p class="kt-adv-heading7_91dbce-e8 wp-block-kadence-advancedheading vf-acc-a" data-kb-block="kb-adv-heading7_91dbce-e8">They're stored under long random names in a folder that blocks direct access on Apache and LiteSpeed. Administrators download them through WordPress. On nginx, ask your host to block wp-content/uploads/vuloform/.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"borderWidth":["","","",""],"uniqueID":"7_b39ee9-38","kbVersion":2,"className":"vf-acc-item"} -->
<div class="wp-block-kadence-column kadence-column7_b39ee9-38 vf-acc-item"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"level":3,"uniqueID":"7_5d99dc-d9","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-acc-q"} -->
<h3 class="kt-adv-heading7_5d99dc-d9 wp-block-kadence-advancedheading vf-acc-q" data-kb-block="kb-adv-heading7_5d99dc-d9">Does “Handed off” mean the email was delivered?</h3>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_4ee5ef-c5","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-acc-a"} -->
<p class="kt-adv-heading7_4ee5ef-c5 wp-block-kadence-advancedheading vf-acc-a" data-kb-block="kb-adv-heading7_4ee5ef-c5">It means your site's mail system accepted it. VuloForm can't see whether it reached the inbox — if mail goes missing, check spam and consider an SMTP plugin such as VuloMail.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"borderWidth":["","","",""],"uniqueID":"7_c2bd4d-87","kbVersion":2,"className":"vf-acc-item"} -->
<div class="wp-block-kadence-column kadence-column7_c2bd4d-87 vf-acc-item"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"level":3,"uniqueID":"7_01663d-9f","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-acc-q"} -->
<h3 class="kt-adv-heading7_01663d-9f wp-block-kadence-advancedheading vf-acc-q" data-kb-block="kb-adv-heading7_01663d-9f">What is removed when I delete the plugin?</h3>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_a9519f-c7","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-acc-a"} -->
<p class="kt-adv-heading7_a9519f-c7 wp-block-kadence-advancedheading vf-acc-a" data-kb-block="kb-adv-heading7_a9519f-c7">Nothing, by default, so a reinstall picks up where you left off. To remove everything, choose “Delete everything” under VuloForm › Settings first.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column --></div></div>
<!-- /wp:kadence/column -->
